    const sets = "\n\nГотовые наборы (op add_set: {set, variant: номер | \"auto\" — самый крупный, что помещается, room}):\n  " + KB.SETS.map(st => `${st.key} — ${st.name}: ${st.variants.map((v, n) => `${n}=${v.name} (${v.w}×${v.h} м)`).join("; ")}`).join("\n  ");
