    const rb = openDesks ? (compact ? 2.6 : 2.8) : (compact ? 3.0 : 3.2);
    const a = compact ? 1.5 : 1.8;   // проход вдоль мест продаж и служебный коридор: ≥ 1,5 м — разворот кресла-коляски (к с/у МГН)
