    /* ---------- 1. служебное ядро (правый торец) */
    const upKeys = mezz ? ["director", "backoffice", "kitchen", "archive", "server", "storage", "wcs", "prayer"] : [];   // персонал — наверх: санузлы персонала и намазхана тоже, внизу остаётся место клиентам
